-- A384: coleção normalizada de lotes por venda, preservando sale_cases.lot_id como lote principal legado.
-- A associação é física/cadastral: uma venda continua tendo uma única negociação,
-- agenda, participação projetada e lote interno nominal. Não há pagamento persistido.

create table public.subdivision_sale_case_lots (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  sale_case_id uuid not null,
  lot_id uuid not null,
  lot_position smallint not null check (lot_position between 1 and 64),
  is_primary boolean not null default false,
  created_by uuid not null references public.identity_subjects(user_id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint subdivision_sale_case_lots_case_tenant_fk foreign key (sale_case_id, organization_id) references public.subdivision_sale_cases(id, organization_id) on delete restrict,
  constraint subdivision_sale_case_lots_lot_tenant_fk foreign key (lot_id, organization_id) references public.subdivision_lots(id, organization_id) on delete restrict,
  constraint subdivision_sale_case_lots_unique_lot unique (organization_id, sale_case_id, lot_id),
  constraint subdivision_sale_case_lots_unique_position unique (organization_id, sale_case_id, lot_position),
  constraint subdivision_sale_case_lots_tenant_match unique (id, organization_id)
);
create unique index subdivision_sale_case_lots_one_primary on public.subdivision_sale_case_lots(organization_id, sale_case_id) where is_primary;
create index subdivision_sale_case_lots_lot_lookup on public.subdivision_sale_case_lots(organization_id, lot_id, sale_case_id);
alter table public.subdivision_sale_case_lots enable row level security;
revoke all on table public.subdivision_sale_case_lots from public, anon, authenticated;
comment on table public.subdivision_sale_case_lots is 'A384: coleção física de lotes por uma venda; sale_cases.lot_id permanece principal legado; sem duplicar agenda, itens nominais ou operações financeiras.';

create or replace function private.validate_subdivision_sale_case_lot_primary() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.is_primary and not exists (select 1 from public.subdivision_sale_cases sale_case where sale_case.id=new.sale_case_id and sale_case.organization_id=new.organization_id and sale_case.lot_id=new.lot_id) then raise exception using errcode='22023',message='SUBDIVISION_SALE_CASE_PRIMARY_LOT_MISMATCH'; end if;
  return new;
end;
$$;
create trigger subdivision_sale_case_lots_primary_guard before insert or update on public.subdivision_sale_case_lots for each row execute function private.validate_subdivision_sale_case_lot_primary();

create or replace function private.subdivision_sale_case_lot_rows(p_organization_id uuid,p_sale_case_id uuid) returns table(lot_id uuid,lot_position smallint,is_primary boolean) language sql security definer set search_path = '' as $$
  with linked as (
    select link.lot_id,link.lot_position,link.is_primary from public.subdivision_sale_case_lots link where link.organization_id=p_organization_id and link.sale_case_id=p_sale_case_id
    union all
    select sale_case.lot_id,1::smallint,true from public.subdivision_sale_cases sale_case where sale_case.organization_id=p_organization_id and sale_case.id=p_sale_case_id and not exists(select 1 from public.subdivision_sale_case_lots link where link.organization_id=p_organization_id and link.sale_case_id=p_sale_case_id)
  ), deduplicated as (
    select distinct on(linked.lot_id) linked.lot_id,linked.lot_position,linked.is_primary from linked order by linked.lot_id,linked.is_primary desc,linked.lot_position
  ) select lot_id,lot_position,is_primary from deduplicated order by is_primary desc,lot_position,lot_id;
$$;
create or replace function private.subdivision_sale_case_lot_ids(p_organization_id uuid,p_sale_case_id uuid) returns uuid[] language sql security definer set search_path = '' as $$ select coalesce(array_agg(rows.lot_id order by rows.lot_id),'{}'::uuid[]) from private.subdivision_sale_case_lot_rows(p_organization_id,p_sale_case_id) rows; $$;
create or replace function private.subdivision_lock_sale_case_lots(p_organization_id uuid,p_sale_case_id uuid) returns uuid[] language plpgsql security definer set search_path = '' as $$
declare v_lot_ids uuid[]; v_lot_id uuid;
begin
  v_lot_ids:=private.subdivision_sale_case_lot_ids(p_organization_id,p_sale_case_id);
  if coalesce(array_length(v_lot_ids,1),0)=0 then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_LOTS_MISSING'; end if;
  foreach v_lot_id in array v_lot_ids loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_organization_id::text||':'||v_lot_id::text,0));
    perform 1 from public.subdivision_lots lot where lot.organization_id=p_organization_id and lot.id=v_lot_id for update;
    if not found then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_LOT_CONTEXT_DENIED'; end if;
  end loop;
  return v_lot_ids;
end;
$$;
create or replace function private.subdivision_lot_has_active_sale(p_organization_id uuid,p_lot_id uuid) returns boolean language sql security definer set search_path = '' as $$ select exists(select 1 from public.subdivision_sale_cases sale_case where sale_case.organization_id=p_organization_id and sale_case.state not in('cancelled','archived') and exists(select 1 from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows where rows.lot_id=p_lot_id)); $$;

create or replace function public.subdivision_open_sale_case_multi(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_lot_ids uuid[],p_buyer_client_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$
declare v_idempotent_case_id uuid; v_existing_case_id uuid; v_existing_buyer_client_id uuid; v_case_id uuid; v_requested_count integer; v_valid_count integer; v_development_count integer; v_development_id uuid; v_fingerprint text; v_existing_fingerprint text; v_lot_id uuid; v_position integer;
begin
  perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);
  if p_module<>'loteadora' then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_CONTEXT_DENIED'; end if;
  v_requested_count:=coalesce(array_length(p_lot_ids,1),0);
  if v_requested_count not between 1 and 64 then raise exception using errcode='22023',message='SUBDIVISION_SALE_CASE_LOT_COUNT_DENIED'; end if;
  if (select count(*) from unnest(p_lot_ids) request(lot_id))<>(select count(distinct request.lot_id) from unnest(p_lot_ids) request(lot_id)) then raise exception using errcode='23505',message='SUBDIVISION_SALE_CASE_LOT_DUPLICATE'; end if;
  v_fingerprint:=(select pg_catalog.array_to_string(pg_catalog.array_agg(request.lot_id::text order by request.lot_id),',') from unnest(p_lot_ids) request(lot_id))||':'||p_buyer_client_id::text;
  select event.target_id,event.payload_redacted->>'lot_fingerprint' into v_idempotent_case_id,v_existing_fingerprint from public.admin_audit_events event where event.command_name='subdivision_open_sale_case_multi' and event.correlation_id=p_correlation_id and event.actor_user_id=p_actor_user_id and event.organization_id=p_organization_id and event.outcome='allowed' order by event.occurred_at desc limit 1;
  if v_idempotent_case_id is not null then if v_existing_fingerprint is distinct from v_fingerprint then raise exception using errcode='22023',message='SUBDIVISION_SALE_CASE_CORRELATION_CONFLICT'; end if; return v_idempotent_case_id; end if;
  if not exists(select 1 from public.subdivision_buyer_clients client join public.party_role_assignments role_assignment on role_assignment.id=client.party_role_assignment_id and role_assignment.organization_id=client.organization_id where client.id=p_buyer_client_id and client.organization_id=p_organization_id and client.state='draft'::public.party_lifecycle_state and role_assignment.module='loteadora' and role_assignment.role in('client','buyer') and role_assignment.state='draft'::public.party_lifecycle_state) then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_BUYER_CONTEXT_DENIED'; end if;
  select count(*)::integer,count(distinct development.id)::integer,(pg_catalog.array_agg(development.id order by development.id))[1] into v_valid_count,v_development_count,v_development_id from unnest(p_lot_ids) request(lot_id) join public.subdivision_lots lot on lot.id=request.lot_id and lot.organization_id=p_organization_id join public.subdivision_blocks block on block.id=lot.block_id and block.organization_id=p_organization_id join public.subdivision_developments development on development.id=block.development_id and development.organization_id=p_organization_id where lot.state='draft'::public.party_lifecycle_state and block.state='draft'::public.party_lifecycle_state and development.state='draft'::public.party_lifecycle_state;
  if v_valid_count<>v_requested_count then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_LOT_CONTEXT_DENIED'; end if;
  if v_development_count<>1 or v_development_id is null then raise exception using errcode='22023',message='SUBDIVISION_SALE_CASE_DEVELOPMENT_MISMATCH'; end if;
  for v_lot_id in select request.lot_id from unnest(p_lot_ids) request(lot_id) order by request.lot_id loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_organization_id::text||':'||v_lot_id::text,0));
    perform 1 from public.subdivision_lots lot where lot.organization_id=p_organization_id and lot.id=v_lot_id for update;
    if exists(select 1 from public.subdivision_lot_physical_reservations reservation where reservation.organization_id=p_organization_id and reservation.lot_id=v_lot_id) then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_PHYSICAL_RESTRICTION'; end if;
  end loop;
  select sale_case.id,sale_case.primary_buyer_client_id into v_existing_case_id,v_existing_buyer_client_id from public.subdivision_sale_cases sale_case where sale_case.organization_id=p_organization_id and sale_case.state not in('cancelled','archived') and not exists(select 1 from unnest(p_lot_ids) request(lot_id) where not exists(select 1 from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows where rows.lot_id=request.lot_id)) and not exists(select 1 from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows where not exists(select 1 from unnest(p_lot_ids) request(lot_id) where request.lot_id=rows.lot_id)) order by sale_case.updated_at desc,sale_case.id limit 1;
  if v_existing_case_id is not null then
    if v_existing_buyer_client_id<>p_buyer_client_id then raise exception using errcode='23505',message='SUBDIVISION_SALE_CASE_LOT_BUSY'; end if;
    for v_lot_id,v_position in select request.lot_id,request.position::integer from unnest(p_lot_ids) with ordinality request(lot_id,position) order by request.position loop
      insert into public.subdivision_sale_case_lots(organization_id,sale_case_id,lot_id,lot_position,is_primary,created_by) values(p_organization_id,v_existing_case_id,v_lot_id,v_position::smallint,v_position=1,p_actor_user_id) on conflict(organization_id,sale_case_id,lot_id) do nothing;
    end loop;
    return v_existing_case_id;
  end if;
  if exists(select 1 from unnest(p_lot_ids) request(lot_id) where private.subdivision_lot_has_active_sale(p_organization_id,request.lot_id)) then raise exception using errcode='23505',message='SUBDIVISION_SALE_CASE_LOT_BUSY'; end if;
  insert into public.subdivision_sale_cases(organization_id,lot_id,primary_buyer_client_id,state,created_by) values(p_organization_id,p_lot_ids[1],p_buyer_client_id,'preparation',p_actor_user_id) returning id into v_case_id;
  insert into public.subdivision_sale_case_lots(organization_id,sale_case_id,lot_id,lot_position,is_primary,created_by) select p_organization_id,v_case_id,request.lot_id,request.position::smallint,request.position=1,p_actor_user_id from unnest(p_lot_ids) with ordinality request(lot_id,position) order by request.position;
  insert into public.subdivision_sale_case_parties(organization_id,sale_case_id,buyer_client_id,party_role,created_by) values(p_organization_id,v_case_id,p_buyer_client_id,'primary_proponent',p_actor_user_id);
  insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted) values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_open_sale_case_multi','allowed','subdivision_sale_case',v_case_id,pg_catalog.jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'lot_fingerprint',v_fingerprint,'physical_lot_count',v_requested_count,'buyer_client_present',true,'primary_proponent_present',true,'state','preparation'));
  return v_case_id;
end;
$$;
create or replace function public.subdivision_open_sale_case(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_lot_id uuid,p_buyer_client_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$ begin return public.subdivision_open_sale_case_multi(p_actor_user_id,p_organization_id,p_module,p_purpose_code,array[p_lot_id]::uuid[],p_buyer_client_id,p_correlation_id); end; $$;
revoke all on function public.subdivision_open_sale_case_multi(uuid,uuid,public.operating_module,text,uuid[],uuid,uuid),public.subdivision_open_sale_case(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.subdivision_open_sale_case_multi(uuid,uuid,public.operating_module,text,uuid[],uuid,uuid),public.subdivision_open_sale_case(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) to service_role;

-- Leitura física aditiva: o lote legado continua no primeiro retorno; physical_lots
-- nunca expõe IDs técnicos, PII ou semântica financeira.
drop function if exists public.subdivision_list_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text);
create function public.subdivision_list_sale_cases_with_physical_lineage(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_case_id uuid,lot_id uuid,buyer_client_id uuid,development_reference text,block_number integer,lot_number integer,state public.subdivision_sale_case_state,terms_version integer,negotiated_total_cents bigint,entry_amount_cents bigint,entry_due_date date,entry_installment_count integer,entry_installment_amount_cents bigint,entry_first_due_date date,entry_due_day integer,entry_installment_schedule jsonb,installment_count integer,installment_amount_cents bigint,first_due_date date,due_day integer,settlement_mode text,cash_settlement_amount_cents bigint,cash_settlement_due_date date,supplemental_amount_cents bigint,supplemental_due_date date,trade_in_credit_cents bigint,trade_in_due_date date,trade_in_category text,trade_in_description text,created_at timestamptz,updated_at timestamptz,physical_lot_count integer,physical_lots jsonb) language plpgsql security definer set search_path = '' as $$ begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); if p_module<>'loteadora' then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_CONTEXT_DENIED'; end if; return query select sale_case.id,primary_link.lot_id,sale_case.primary_buyer_client_id,development.internal_reference,block.block_number,lot.lot_number,sale_case.state,terms.version_number,terms.negotiated_total_cents,terms.entry_amount_cents,terms.entry_due_date,coalesce(terms.entry_installment_count,0),terms.entry_installment_amount_cents,terms.entry_first_due_date,terms.entry_due_day,coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('installment_number',item.installment_number,'amount_cents',item.amount_cents,'due_date',item.due_date) order by item.installment_number) from public.subdivision_sale_case_entry_installments item where item.organization_id=sale_case.organization_id and item.sale_case_id=sale_case.id),'[]'::jsonb),coalesce(terms.installment_count,0),terms.installment_amount_cents,terms.first_due_date,terms.due_day,terms.settlement_mode,terms.cash_settlement_amount_cents,terms.cash_settlement_due_date,terms.supplemental_amount_cents,terms.supplemental_due_date,terms.trade_in_credit_cents,terms.trade_in_due_date,terms.trade_in_category,terms.trade_in_description,sale_case.created_at,sale_case.updated_at,physical.physical_lot_count,physical.physical_lots from public.subdivision_sale_cases sale_case join lateral(select rows.lot_id from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows order by rows.is_primary desc,rows.lot_position,rows.lot_id limit 1) primary_link on true join public.subdivision_lots lot on lot.id=primary_link.lot_id and lot.organization_id=sale_case.organization_id join public.subdivision_blocks block on block.id=lot.block_id and block.organization_id=lot.organization_id join public.subdivision_developments development on development.id=block.development_id and development.organization_id=block.organization_id left join public.subdivision_sale_case_terms terms on terms.sale_case_id=sale_case.id and terms.organization_id=sale_case.organization_id left join lateral(select count(*)::integer as physical_lot_count,coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('position',rows.lot_position,'is_primary',rows.is_primary,'development_reference',row_development.internal_reference,'block_number',row_block.block_number,'lot_number',row_lot.lot_number) order by rows.lot_position,rows.lot_id),'[]'::jsonb) as physical_lots from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows join public.subdivision_lots row_lot on row_lot.id=rows.lot_id and row_lot.organization_id=p_organization_id join public.subdivision_blocks row_block on row_block.id=row_lot.block_id and row_block.organization_id=p_organization_id join public.subdivision_developments row_development on row_development.id=row_block.development_id and row_development.organization_id=p_organization_id) physical on true where sale_case.organization_id=p_organization_id and sale_case.state<>'archived' order by sale_case.updated_at desc,sale_case.id; end; $$;
revoke all on function public.subdivision_list_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text) from public,anon,authenticated; grant execute on function public.subdivision_list_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text) to service_role;

drop function if exists public.subdivision_list_archived_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text);
create function public.subdivision_list_archived_sale_cases_with_physical_lineage(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_case_id uuid,lot_id uuid,buyer_client_id uuid,development_reference text,block_number integer,lot_number integer,state public.subdivision_sale_case_state,terms_version integer,negotiated_total_cents bigint,entry_amount_cents bigint,entry_due_date date,entry_installment_count integer,entry_installment_amount_cents bigint,entry_first_due_date date,entry_due_day integer,entry_installment_schedule jsonb,installment_count integer,installment_amount_cents bigint,first_due_date date,due_day integer,settlement_mode text,cash_settlement_amount_cents bigint,cash_settlement_due_date date,supplemental_amount_cents bigint,supplemental_due_date date,trade_in_credit_cents bigint,trade_in_due_date date,trade_in_category text,trade_in_description text,created_at timestamptz,updated_at timestamptz,physical_lot_count integer,physical_lots jsonb) language plpgsql security definer set search_path = '' as $$ begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); if p_module<>'loteadora' then raise exception using errcode='42501',message='SUBDIVISION_SALE_CASE_CONTEXT_DENIED'; end if; return query select sale_case.id,primary_link.lot_id,sale_case.primary_buyer_client_id,development.internal_reference,block.block_number,lot.lot_number,sale_case.state,terms.version_number,terms.negotiated_total_cents,terms.entry_amount_cents,terms.entry_due_date,coalesce(terms.entry_installment_count,0),terms.entry_installment_amount_cents,terms.entry_first_due_date,terms.entry_due_day,coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('installment_number',item.installment_number,'amount_cents',item.amount_cents,'due_date',item.due_date) order by item.installment_number) from public.subdivision_sale_case_entry_installments item where item.organization_id=sale_case.organization_id and item.sale_case_id=sale_case.id),'[]'::jsonb),coalesce(terms.installment_count,0),terms.installment_amount_cents,terms.first_due_date,terms.due_day,terms.settlement_mode,terms.cash_settlement_amount_cents,terms.cash_settlement_due_date,terms.supplemental_amount_cents,terms.supplemental_due_date,terms.trade_in_credit_cents,terms.trade_in_due_date,terms.trade_in_category,terms.trade_in_description,sale_case.created_at,sale_case.updated_at,physical.physical_lot_count,physical.physical_lots from public.subdivision_sale_cases sale_case join lateral(select rows.lot_id from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows order by rows.is_primary desc,rows.lot_position,rows.lot_id limit 1) primary_link on true join public.subdivision_lots lot on lot.id=primary_link.lot_id and lot.organization_id=sale_case.organization_id join public.subdivision_blocks block on block.id=lot.block_id and block.organization_id=lot.organization_id join public.subdivision_developments development on development.id=block.development_id and development.organization_id=block.organization_id left join public.subdivision_sale_case_terms terms on terms.sale_case_id=sale_case.id and terms.organization_id=sale_case.organization_id left join lateral(select count(*)::integer as physical_lot_count,coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('position',rows.lot_position,'is_primary',rows.is_primary,'development_reference',row_development.internal_reference,'block_number',row_block.block_number,'lot_number',row_lot.lot_number) order by rows.lot_position,rows.lot_id),'[]'::jsonb) as physical_lots from private.subdivision_sale_case_lot_rows(p_organization_id,sale_case.id) rows join public.subdivision_lots row_lot on row_lot.id=rows.lot_id and row_lot.organization_id=p_organization_id join public.subdivision_blocks row_block on row_block.id=row_lot.block_id and row_block.organization_id=p_organization_id join public.subdivision_developments row_development on row_development.id=row_block.development_id and row_development.organization_id=p_organization_id) physical on true where sale_case.organization_id=p_organization_id and sale_case.state='archived' order by sale_case.updated_at desc,sale_case.id; end; $$;
revoke all on function public.subdivision_list_archived_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text) from public,anon,authenticated; grant execute on function public.subdivision_list_archived_sale_cases_with_physical_lineage(uuid,uuid,public.operating_module,text) to service_role;
comment on function public.subdivision_open_sale_case_multi(uuid,uuid,public.operating_module,text,uuid[],uuid,uuid) is 'A384: abre uma única venda para conjunto não vazio do mesmo empreendimento; mantém lote principal legado, locks e idempotência; não duplica itens nominais.';
